const FRAGEN = [
  {"thema": "statik", "quelle": "MEC1-Prüfungsfragen 2014", "frage": "Was besagt das Parallelogrammaxiom?", "richtig": "Zwei Kräfte mit gemeinsamem Angriffspunkt sind gleichwertig einer Kraft, die durch Vektoraddition F = F₁ + F₂ entsteht.", "falsch": ["Zwei beliebige Kräfte am starren Körper sind gleichwertig der Summe ihrer Beträge |F₁| + |F₂| in Richtung der größeren Kraft.", "Eine Kraft darf parallel zu sich selbst verschoben werden, solange ihr Betrag und ihre Richtung gleich bleiben.", "Zwei Kräfte mit gemeinsamem Angriffspunkt heben sich auf, wenn sie ein Parallelogramm mit gleich langen Seiten bilden."], "musterantwort": "Das Parallelogrammaxiom besagt, dass die Wirkung zweier Kräfte F₁ und F₂ mit gemeinsamem Angriffspunkt gleichwertig der Wirkung einer einzigen Kraft F ist. F ist die Diagonale des von F₁ und F₂ aufgespannten Kräfteparallelogramms, also die Vektorsumme F = F₁ + F₂.", "erklaerung": "Kräfte werden vektoriell addiert, nicht ihre Beträge – und nur bei gemeinsamem Angriffspunkt.", "seiten": "Prüfungsfragen 2014, Statik starrer Körper – Axiome"},
  {"thema": "statik", "quelle": "MEC1-Prüfungsfragen 2014", "frage": "Was besagt das Verschiebungsaxiom (Verschiebeaxiom)?", "richtig": "Die Wirkung einer Kraft auf einen starren Körper bleibt gleich, wenn ihr Angriffspunkt entlang der Wirkungslinie verschoben wird.", "falsch": ["Eine Kraft darf an einem starren Körper beliebig parallel zu ihrer Wirkungslinie verschoben werden, ohne dass sich die Wirkung ändert.", "Die Wirkung einer Kraft bleibt auch am verformbaren Körper gleich, wenn man sie entlang ihrer Wirkungslinie verschiebt.", "Eine Kraft darf in jeden Punkt des Körpers verschoben werden, wenn man ihren Betrag entsprechend verkleinert."], "musterantwort": "Am starren Körper ist eine Kraft ein linienflüchtiger Vektor: Der Angriffspunkt darf entlang der Wirkungslinie verschoben werden, ohne dass sich die Wirkung auf den Körper ändert. Eine Parallelverschiebung ist dagegen nur mit zusätzlichem Versatzmoment statisch äquivalent. Für verformbare Körper gilt das Axiom nicht (innere Beanspruchung ändert sich).", "erklaerung": "Verschieben nur entlang der Wirkungslinie – parallel verschieben braucht ein Versatzmoment.", "seiten": "Prüfungsfragen 2014, Statik starrer Körper – Axiome"},
  {"thema": "statik", "quelle": "MEC1-Prüfungsfragen 2014", "frage": "Was besagt das Trägheitsaxiom?", "richtig": "Ein Körper verharrt in Ruhe oder gleichförmiger Bewegung, solange keine resultierende Kraft wirkt.", "falsch": ["Ein Körper bleibt nur dann in Ruhe, wenn überhaupt keine einzige Kraft auf ihn einwirkt, auch keine sich aufhebende.", "Kräfte, die zwei Körper aufeinander ausüben, sind gleich groß und entgegengesetzt gerichtet.", "Ein Körper bewegt sich gleichförmig, solange eine konstante resultierende Kraft auf ihn wirkt."], "musterantwort": "Das Trägheitsaxiom (1. Newtonsches Axiom) besagt, dass ein Körper im Zustand der Ruhe oder der gleichförmigen geradlinigen Bewegung verharrt, solange keine resultierende Kraft auf ihn einwirkt. Daraus folgt die Gleichgewichtsbedingung R = ΣFᵢ = 0 (und beim allgemeinen Kraftsystem zusätzlich M = 0).", "erklaerung": "Entscheidend ist die Resultierende – es dürfen sehr wohl Kräfte wirken, wenn sie sich aufheben.", "seiten": "Prüfungsfragen 2014, Statik starrer Körper – Axiome"},
  {"thema": "statik", "quelle": "MEC1-Fragenkatalog (Ausarbeitung)", "frage": "Was besagt das Reaktionsaxiom?", "richtig": "Kräfte zwischen zwei Körpern sind gleich groß, entgegengesetzt und liegen auf derselben Wirkungslinie.", "falsch": ["Jede Lagerreaktion ist gleich groß wie die größte am Körper angreifende äußere Kraft.", "Zwei Kräfte am selben Körper sind immer im Gleichgewicht, sobald sie gleich groß und entgegengesetzt gerichtet sind.", "Die Reaktionskraft eines Körpers ist immer halb so groß wie die einwirkende Kraft."], "musterantwort": "Das Reaktionsaxiom (actio = reactio) besagt: Übt Körper 1 auf Körper 2 eine Kraft aus, so übt Körper 2 auf Körper 1 eine gleich große, entgegengesetzt gerichtete Kraft auf derselben Wirkungslinie aus. Die beiden Kräfte greifen an verschiedenen Körpern an – deshalb ist das kein Gleichgewicht am selben Körper. Beim Freischneiden werden Schnittkräfte daher an beiden Schnittufern entgegengesetzt angetragen.", "erklaerung": "Actio und Reactio wirken auf verschiedene Körper – nicht mit dem Gleichgewicht zweier Kräfte am selben Körper verwechseln.", "seiten": "MEC1 Ausarbeitung, 1.2 Axiome"},
  {"thema": "statik", "quelle": "MEC1-Prüfungsfragen 2014", "frage": "Wann liegt ein zentrales Kraftsystem (ZK) vor?", "richtig": "Wenn sich die Wirkungslinien aller Kräfte in einem gemeinsamen Punkt schneiden.", "falsch": ["Wenn alle Kräfte parallel zueinander verlaufen und zusätzlich alle gleich gerichtet sind.", "Wenn alle Kräfte im Schwerpunkt des Körpers angreifen müssen.", "Wenn die Resultierende aller Kräfte durch den Schwerpunkt geht."], "musterantwort": "Ein zentrales (ebenes oder räumliches) Kraftsystem liegt vor, wenn sich die Wirkungslinien aller Kräfte F₁ … Fₙ in einem Punkt P schneiden. Die Angriffspunkte selbst müssen nicht zusammenfallen, da die Kräfte nach dem Verschiebungsaxiom entlang ihrer Wirkungslinien nach P verschoben werden dürfen. Ein gemeinsamer Angriffspunkt ist dafür nicht nötig.", "erklaerung": "Es zählt der Schnittpunkt der Wirkungslinien, nicht ein gemeinsamer Angriffspunkt.", "seiten": "Prüfungsfragen 2014, Statik starrer Körper – Das zentrale Kraftsystem"},
  {"thema": "statik", "quelle": "MEC1-Prüfungsfragen 2014", "frage": "Warum können alle Kräfte eines zentralen Kraftsystems zu einer einzigen resultierenden Kraft zusammengefasst werden? (Begründung mit Axiomen)", "richtig": "Mit dem Verschiebungsaxiom alle Kräfte in den Schnittpunkt verschieben, dann mit dem Parallelogrammaxiom paarweise addieren.", "falsch": ["Mit dem Trägheitsaxiom alle Kräfte gleich null setzen und anschließend mit dem Reaktionsaxiom die jeweilige Gegenkraft bestimmen.", "Mit dem Parallelogrammaxiom alle Kräfte parallel in den Schwerpunkt verschieben und dort die Beträge addieren.", "Mit dem Reaktionsaxiom jede Kraft durch ihre Gegenkraft ersetzen und danach ein Versatzmoment ergänzen."], "musterantwort": "Nach dem Verschiebungsaxiom dürfen alle Kräfte entlang ihrer Wirkungslinien in den gemeinsamen Schnittpunkt P verschoben werden. Dort fasst man nach dem Parallelogrammaxiom jeweils zwei Kräfte zu einer zusammen; nach n−1 Schritten bleibt nur die Resultierende R = ΣFᵢ übrig. Ein Versatzmoment entsteht dabei nicht.", "erklaerung": "Verschiebungsaxiom + Parallelogrammaxiom – beim ZK entsteht kein Moment.", "seiten": "Prüfungsfragen 2014, Statik starrer Körper – Das zentrale Kraftsystem"},
  {"thema": "statik", "quelle": "MEC1-Prüfungsfragen 2014", "frage": "Wann ist ein zentrales Kraftsystem in Ruhe (im Gleichgewicht)?", "richtig": "Wenn die Resultierende verschwindet: R = ΣFᵢ = 0, im Raum also ΣFx = ΣFy = ΣFz = 0.", "falsch": ["Wenn die Summe der Beträge aller Kräfte null ist: Σ|Fᵢ| = 0.", "Wenn zusätzlich zu R = 0 auch die Momentensumme um jeden Punkt eigens gefordert wird (6 Gleichungen in der Ebene).", "Wenn alle Kräfte gleich groß sind und symmetrisch um den Schnittpunkt verteilt sind."], "musterantwort": "Nach dem Trägheitsaxiom ist ein zentrales Kraftsystem genau dann in Ruhe, wenn die resultierende Kraft null ist: R = ΣFᵢ = 0. Das sind im Raum drei, in der Ebene zwei skalare Gleichungen. Eine eigene Momentenbedingung ist nicht nötig, weil alle Wirkungslinien durch einen Punkt gehen und um diesen kein Moment entsteht.", "erklaerung": "Beim ZK reicht R = 0 – in der Ebene also 2 Gleichungen, nicht 3.", "seiten": "Prüfungsfragen 2014, Statik starrer Körper – Das zentrale Kraftsystem"},
  {"thema": "statik", "quelle": "MEC1-Prüfungsfragen 2014", "frage": "Wie ist das Drehmoment einer Kraft F um einen Bezugspunkt A definiert?", "richtig": "M_A = r_AP × F, r_AP von A zu einem Punkt P der Wirkungslinie; Betrag = Kraft · Normalabstand.", "falsch": ["M_A = F × r_AP, mit r_AP vom Angriffspunkt P zurück zum Bezugspunkt A; Betrag = Kraft · Normalabstand.", "M_A = r_AP · F (Skalarprodukt); Betrag = Kraft · Abstand zum Angriffspunkt.", "M_A = |r_AP| · |F|, unabhängig vom Winkel zwischen Hebelarm und Kraft."], "musterantwort": "Das Moment einer Kraft bezüglich A ist das Kreuzprodukt M_A = r_AP × F, wobei r_AP vom Bezugspunkt A zu einem beliebigen Punkt P auf der Wirkungslinie zeigt. Der Betrag ist |r|·|F|·sin φ = |F|·d mit d als Normalabstand der Wirkungslinie von A; die Richtung steht senkrecht auf der von r und F aufgespannten Ebene (Rechte-Hand-Regel).", "erklaerung": "Reihenfolge r × F beachten – das Skalarprodukt liefert kein Moment.", "seiten": "Prüfungsfragen 2014, Statik starrer Körper – Drehmoment"},
  {"thema": "statik", "quelle": "MEC1-Prüfungsfragen 2014", "frage": "Wie ist ein Kräftepaar definiert und von welchem Bezugspunkt hängt sein Moment ab?", "richtig": "Zwei parallele, gleich große, entgegengesetzte Kräfte; ihr Moment d·|F| ist vom Bezugspunkt unabhängig.", "falsch": ["Zwei parallele, gleich große, gleich gerichtete Kräfte; ihr Moment hängt vom Abstand zum gewählten Bezugspunkt ab.", "Zwei gleich große, entgegengesetzte Kräfte auf derselben Wirkungslinie; ihr Moment ist d·|F|.", "Zwei parallele, entgegengesetzte Kräfte; ihr Moment muss immer um den Mittelpunkt zwischen ihnen gebildet werden."], "musterantwort": "Ein Kräftepaar besteht aus zwei parallelen, betragsgleichen, entgegengesetzt gerichteten Kräften mit Abstand d. Die verschiebende Wirkung ist null, die verdrehende M = d·|F|. Formal: M_O = r₁ × F + r₂ × (−F) = (r₁ − r₂) × F – nur die Differenz der Ortsvektoren geht ein, daher ist das Moment für jeden Bezugspunkt O gleich (freier Vektor).", "erklaerung": "Kräftepaar-Moment ist ein freier Vektor – Bezugspunkt egal.", "seiten": "Prüfungsfragen 2014, Statik starrer Körper – Drehmoment eines Kräftepaares"},
  {"thema": "statik", "quelle": "MEC1-Prüfungsfragen 2014", "frage": "Warum muss bei einer statisch äquivalenten (Parallel-)Verschiebung einer Kraft von P nach A ein Versatzmoment berücksichtigt werden, und wie lautet es?", "richtig": "In A werden +F und −F ergänzt; F in P und −F in A bilden ein Kräftepaar: M_A = r_AP × F.", "falsch": ["Weil die Kraft beim Verschieben kleiner wird; das Versatzmoment ist M = |F|·|r_AP|² .", "Weil sonst das Reaktionsaxiom verletzt wäre, da die Kraft nicht mehr am Körper angreift; M_A = F × r_AP.", "Weil sich der Schwerpunkt verschiebt; das Versatzmoment ist M_A = r_AP · F (Skalarprodukt)."], "musterantwort": "Verschiebt man F nicht entlang, sondern parallel zur Wirkungslinie, ändert sich die Drehwirkung. Man ergänzt in A ein Nullsystem aus +F und −F: Übrig bleiben F in A sowie das Kräftepaar aus F (in P) und −F (in A). Dieses Kräftepaar ist das Versatzmoment M_A = r_AP × F mit r_AP von A nach P.", "erklaerung": "Parallelverschiebung = Kraft + Versatzmoment r × F.", "seiten": "Prüfungsfragen 2014, Statik starrer Körper – Versatzmoment"},
  {"thema": "statik", "quelle": "MEC1-Prüfungsfragen 2014", "frage": "Wie lauten die Gleichgewichtsbedingungen für ein allgemeines räumliches Kraftsystem?", "richtig": "ΣFᵢ = 0 und Σ(rᵢ × Fᵢ) + ΣMⱼ = 0, also 6 skalare Gleichungen.", "falsch": ["R = ΣFᵢ = 0 genügt, also 3 skalare Gleichungen.", "ΣM = 0 um drei beliebige Punkte genügt, also 3 skalare Gleichungen.", "R = 0 und M_O = 0, zusammen 3 skalare Gleichungen wie im ebenen Fall, da sich Momente addieren."], "musterantwort": "Jedes Kraftsystem lässt sich auf eine resultierende Kraft R und ein resultierendes Moment M_O um einen beliebigen Punkt O reduzieren (Kräfte nach O verschieben, Versatzmomente aufsummieren). Gleichgewicht verlangt R = 0 und M_O = 0: ΣFx = ΣFy = ΣFz = 0 und ΣMx = ΣMy = ΣMz = 0 – also 6 Gleichungen (in der Ebene 3).", "erklaerung": "Raum: 6 Gleichgewichtsbedingungen, Ebene: 3.", "seiten": "Prüfungsfragen 2014, Statik starrer Körper – Allgemeines Kraftsystem"},
  {"thema": "statik", "quelle": "MEC1-Prüfungsfragen 2014", "frage": "Wie berechnet sich der Ortsvektor des Kraftmittelpunkts K einer parallelen Kraftgruppe (z. B. Schwerkraft) bzw. der Schwerpunkt eines Körpers?", "richtig": "r_K = Σ|Fᵢ|·rᵢ / Σ|Fᵢ|; für die Schwerkraft r_S = (1/m)·∫ r dm.", "falsch": ["r_K = Σrᵢ / n; für die Schwerkraft r_S = (1/V)·∫ r² dV.", "r_K = Σ|Fᵢ|·rᵢ ohne Division; für die Schwerkraft r_S = ∫ r dm über den Körper.", "r_K = Σ|Fᵢ| / Σrᵢ; für die Schwerkraft r_S = m / ∫ r dm."], "musterantwort": "Man bildet die Momentensumme der parallelen Kräfte Fᵢ = |Fᵢ|·e um einen noch unbekannten Punkt K und fordert sie null – unabhängig von der Kraftrichtung e: Σ|Fᵢ|(rᵢ − r_K) = 0. Daraus folgt r_K = Σ|Fᵢ| rᵢ / Σ|Fᵢ|. Mit ΔFᵢ = g·Δmᵢ und Grenzübergang Summe → Integral ergibt sich der Schwerpunkt r_S = (1/m)∫ r dm; dort greift die Gewichtskraft G = m·g an.", "erklaerung": "Gewichtetes Mittel der Ortsvektoren – durch die Gesamtkraft bzw. Gesamtmasse teilen.", "seiten": "Prüfungsfragen 2014, Statik starrer Körper – Schwerkraft, Schwerpunkt"},
  {"thema": "reibung", "quelle": "MEC1-Prüfungsfragen 2014", "frage": "Wie groß ist das Reibmoment eines Querlagers (Radiallager, Zapfenradius r, Lagerlast F) und eines Längslagers mit vollem Spurzapfen (Radius r, gleichmäßige Flächenpressung)?", "richtig": "Querlager: M_R = μ·F·r; Längslager: M_R = (2/3)·μ·F·r.", "falsch": ["Querlager: M_R = (2/3)·μ·F·r; Längslager: M_R = μ·F·r.", "Querlager: M_R = μ·F·r; Längslager: M_R = (1/2)·μ·F·r².", "Querlager: M_R = μ·F/r; Längslager: M_R = (2/3)·μ·F/r."], "musterantwort": "Beim Querlager wirkt die Reibkraft μ·F am Zapfenumfang, also M_R = μ·F·r. Beim Längslager verteilt sich F gleichmäßig auf die Kreisfläche (p = F/(πr²)); ein Kreisring der Breite dρ liefert dM = μ·p·2πρ dρ·ρ. Integration von 0 bis r ergibt M_R = μ·p·(2/3)πr³ = (2/3)·μ·F·r.", "erklaerung": "Beim Spurzapfen liegt der wirksame Hebelarm bei 2/3 r, nicht bei r.", "seiten": "Prüfungsfragen 2014, Reibmoment in Lagern; Zusammenfassung 2016, S. 1"},
  {"thema": "reibung", "quelle": "MEC1-Prüfungsfragen 2014", "frage": "Welcher Zusammenhang zwischen Normalkraft N und Reibkraft F_R gilt bei Rollreibung (Rollenradius r, Hebelarm der Rollreibung f)?", "richtig": "F_R = (f/r)·N, weil N wegen kleiner Kontaktverformung um f vor der Mitte angreift.", "falsch": ["F_R = μ·N – wie bei der Gleitreibung, unabhängig vom Rollenradius.", "F_R = (r/f)·N – je größer der Rollenradius, desto größer wird der Rollwiderstand.", "F_R = f·r·N – weil das Rollreibmoment f·N mit dem Radius multipliziert wird."], "musterantwort": "Modellvorstellung: Rolle und Unterlage verformen sich im Kontaktbereich leicht, sodass die resultierende Normalkraft N um den Hebelarm f vor dem Lot durch den Mittelpunkt angreift. Momentengleichgewicht um den Mittelpunkt (mit r* ≈ r bei kleinen Verformungen) liefert F·r = N·f, also F_R = (f/r)·N. f hat die Einheit einer Länge.", "erklaerung": "Große Räder rollen leichter: F_R ~ 1/r.", "seiten": "Prüfungsfragen 2014, Rollreibung; Zusammenfassung 2016, S. 1"},
  {"thema": "reibung", "quelle": "MEC1-Prüfungsfragen 2014", "frage": "Wie lautet die Eytelwein’sche Gleichung (Seilreibung) für die Seilkräfte F_S2 > F_S1 beim beginnenden Rutschen?", "richtig": "F_S2 = F_S1·e^(μ·α), α = Umschlingungswinkel im Bogenmaß (F_S2 = größere Seilkraft).", "falsch": ["F_S2 = F_S1·e^(μ·α), α = Umschlingungswinkel in Grad.", "F_S2 = F_S1·(1 + μ·α), α = Umschlingungswinkel im Bogenmaß.", "F_S2 = F_S1·e^(−μ·α), α = Umschlingungswinkel im Bogenmaß."], "musterantwort": "Für ein über eine Trommel gelegtes Seil gilt an der Rutschgrenze F_S2 = F_S1·e^(μα), wobei F_S2 die größere (ziehende) Seilkraft, μ die Reibzahl und α der Umschlingungswinkel in rad ist. Bei Haftreibung gilt F_S1 ≤ F_S2 ≤ F_S1·e^(μ_H α); bei Gleiten ist die Reibkraft eingeprägt: F_R = F_S2 − F_S1 = F_S1(e^(μ_G α) − 1).", "erklaerung": "Winkel immer im Bogenmaß – eine volle Umschlingung ist 2π.", "seiten": "Prüfungsfragen 2014, Seilreibung; Zusammenfassung 2016, S. 2"},
  {"thema": "reibung", "quelle": "MEC1-Prüfungsfragen 2014", "frage": "Seil auf einer feststehenden Trommel, Haftreibung (kein Rutschen). In welchem Bereich kann die größere Seilkraft F_S2 bei gegebenem F_S1 liegen, und wie wird die Reibkraft behandelt?", "richtig": "F_S1 ≤ F_S2 ≤ F_S1·e^(μ_H·α); die Reibkraft ist eine Zwangskraft aus dem Gleichgewicht.", "falsch": ["F_S2 = F_S1·e^(μ_H·α) gilt exakt; die Reibkraft ist dabei eine eingeprägte, bekannte Kraft.", "F_S2 ≥ F_S1·e^(μ_H·α); die Reibkraft ist immer μ_H·F_S1.", "F_S2 ≤ F_S1·e^(μ_G·α); die Reibkraft ist mit der Gleitreibungszahl vorgegeben."], "musterantwort": "Solange das Seil haftet, ist die Reibkraft F_R = F_S2 − F_S1 eine Reaktions- (Zwangs-)kraft, die aus den Gleichgewichtsbedingungen folgt. Sie kann höchstens so groß werden, dass die Eytelwein-Grenze erreicht ist: F_S1 ≤ F_S2 ≤ F_S1·e^(μ_H α). Erst bei Überschreiten beginnt Gleiten; dann ist F_R eingeprägt mit F_S2 = F_S1·e^(μ_G α).", "erklaerung": "Haften: Reibkraft unbekannt, nur nach oben begrenzt – Gleiten: Reibkraft vorgegeben.", "seiten": "Prüfungsfragen 2014, Seilreibung; Zusammenfassung 2016, S. 2"},
  {"thema": "statik", "quelle": "MEC1-Prüfungsfragen 2014", "frage": "Was ist der erste Schritt der systematischen Vorgehensweise zur Berechnung der Schnittgrößen am geraden Balken, und wie wird der Balken danach eingeteilt?", "richtig": "Zuerst die Auflagerreaktionen; dann Abschnitte, die an jeder Änderung der Belastung enden.", "falsch": ["Zuerst den Momentenverlauf skizzieren; dann den Balken in gleich lange Abschnitte teilen.", "Zuerst die Biegelinie aus der Differentialgleichung berechnen; dann Abschnitte nur an den Lagern bilden.", "Zuerst Querschnittswerte bestimmen; dann Abschnitte an der Stelle des maximalen Moments bilden."], "musterantwort": "1) Auflagerreaktionen mit den Gleichgewichtsbedingungen berechnen. 2) Balken in Abschnitte einteilen – ein Abschnitt endet, wo sich die Belastung ändert (Einzellast, Lager, Beginn/Ende Streckenlast, Einzelmoment). 3) Schnittgrößen N, Q, M je Abschnitt durch Freischneiden bestimmen. 4) Werte an den Abschnittsenden und besondere Punkte (z. B. M_max bei Q = 0) berechnen. 5) Verläufe zeichnen.", "erklaerung": "Abschnittsgrenzen dort, wo sich die Belastungssituation ändert.", "seiten": "Prüfungsfragen 2014, Schnittgrößen am geraden Balken"},
  {"thema": "statik", "quelle": "MEC1-Fragenkatalog (Ausarbeitung)", "frage": "Welche Zusammenhänge gelten zwischen Streckenlast q(x), Querkraft Q(x) und Biegemoment M(x), und wo liegt das maximale Moment?", "richtig": "dQ/dx = −q, dM/dx = Q; das Moment ist extremal, wo die Querkraft null wird.", "falsch": ["dQ/dx = M(x), dM/dx = −q(x); das maximale Moment liegt dort, wo die Streckenlast null wird.", "dQ/dx = −q(x), dM/dx = Q(x); das Maximum liegt immer in Balkenmitte.", "dM/dx = −q(x), dQ/dx = 0; das Maximum liegt dort, wo die Querkraft maximal ist."], "musterantwort": "Aus dem Gleichgewicht am Balkenelement dx folgt dQ/dx = −q und dM/dx = Q (Vorzeichen nach üblicher Konvention). Ohne Streckenlast ist Q konstant und M linear; bei Gleichlast ist Q linear und M eine Parabel. Das Moment hat ein Extremum, wo dM/dx = Q = 0 ist (Nulldurchgang bzw. Vorzeichenwechsel der Querkraft).", "erklaerung": "M_max beim Nulldurchgang von Q suchen.", "seiten": "Buchner-Bernhofer, S. 8–9: Zusammenhang Biegemoment, Querkraft und Last"},
  {"thema": "statik", "quelle": "MEC1-Prüfungsfragen 2014", "frage": "Was versteht man unter einem (idealen) Fachwerk?", "richtig": "Gerade Stäbe, gelenkig in Knoten verbunden, Lasten nur in Knoten – Stäbe tragen nur Zug oder Druck.", "falsch": ["Biegesteif verschweißte Träger, die ihre Lasten hauptsächlich über Biegemomente in die Lager abtragen.", "Gerade Stäbe mit gelenkigen Knoten, auf die Lasten bevorzugt in Stabmitte aufgebracht werden.", "Ein Tragwerk aus Seilen, das nur Zugkräfte aufnehmen kann und keine Lager braucht."], "musterantwort": "Ein ideales Fachwerk besteht aus geraden Stäben, die in den Knotenpunkten durch reibungsfreie Gelenke verbunden sind. Äußere Lasten und Lagerkräfte greifen nur in den Knoten an. Dadurch ist jeder Stab ein Zweigelenkstab (Pendelstab) und überträgt nur eine Normalkraft (Zug oder Druck) in Stabrichtung.", "erklaerung": "Fachwerkstäbe: nur Normalkraft, keine Biegung – Lasten in die Knoten.", "seiten": "Prüfungsfragen 2014, Fachwerk"},
  {"thema": "statik", "quelle": "MEC1-Prüfungsfragen 2014", "frage": "Wann ist ein ebenes Fachwerk mit k Knoten, s Stäben und r Lagerreaktionen statisch bestimmt?", "richtig": "Bei 2·k = s + r (notwendig); 2k < s + r: überbestimmt, 2k > s + r: unterbestimmt (Ausnahmefälle beachten).", "falsch": ["Bei 2·k = s + r; ist 2k < s + r, ist es unterbestimmt, ist 2k > s + r, überbestimmt.", "Wenn k = s + r gilt; k < s + r: überbestimmt, k > s + r: unterbestimmt.", "Wenn 3·k = s + r gilt; 3k < s + r: überbestimmt, 3k > s + r: unterbestimmt."], "musterantwort": "Pro Knoten stehen in der Ebene 2 Gleichgewichtsgleichungen zur Verfügung (a = 2, im Raum a = 3), also 2k Gleichungen. Unbekannt sind s Stabkräfte und r Lagerkräfte. Bei 2k = s + r ist das Fachwerk statisch bestimmt, bei 2k < s + r statisch überbestimmt (mehr Unbekannte als Gleichungen), bei 2k > s + r statisch unterbestimmt (beweglich). Die Abzählbedingung ist notwendig, aber nicht hinreichend (Ausnahmefall/Wackelfachwerk).", "erklaerung": "Mehr Unbekannte als Gleichungen = überbestimmt – nicht umgekehrt.", "seiten": "Prüfungsfragen 2014, Fachwerk; Wagner-Ausarbeitung, Frage 12a"},
  {"thema": "statik", "quelle": "MEC1-Prüfungsfragen 2014", "frage": "Welche systematische Vorgehensweise liefert die Stabkräfte eines statisch bestimmten Fachwerks immer?", "richtig": "Alle Knoten freischneiden, Stabkräfte vom Knoten weg (Zug) ansetzen, je Knoten ΣFx = ΣFy = 0 lösen.", "falsch": ["Den Ritterschnitt durch beliebig viele Stäbe legen und nur die Momentensumme um einen Lagerpunkt bilden.", "Alle Knoten freischneiden, Stabkräfte zum Knoten hin als Zug ansetzen und für jeden Knoten ΣM = 0 aufstellen.", "Die Stabkräfte aus der Stablänge mal Eigengewicht bestimmen und dann die Lagerkräfte addieren."], "musterantwort": "Knotenschnittverfahren: Lagerkräfte einzeichnen, Knoten und Stäbe nummerieren, alle k Knoten freischneiden, wobei Stabkräfte vom Knoten weg (als Zug positiv) angesetzt werden. Für jeden Knoten ΣFx = 0 und ΣFy = 0 (räumlich zusätzlich ΣFz = 0) aufstellen und die 2k Gleichungen nach den Stab- und Lagerkräften lösen. Negatives Ergebnis = Druckstab. Alternativ: Lagerkräfte am Gesamtsystem und gezieltes sukzessives Freischneiden (Ritterschnitt mit höchstens 3 unbekannten Stäben).", "erklaerung": "Stabkräfte vom Knoten weg ansetzen: positives Ergebnis = Zug, negatives = Druck.", "seiten": "Prüfungsfragen 2014, Fachwerk; MEC1 Ausarbeitung 13.1"},
  {"thema": "lager", "quelle": "MEC1-Fragenkatalog (Ausarbeitung)", "frage": "Wie viele Lagerreaktionen liefern in der Ebene ein Loslager, ein Festlager und eine feste Einspannung?", "richtig": "Loslager 1 Kraft, Festlager 2 Kräfte, Einspannung 2 Kräfte und 1 Moment.", "falsch": ["Loslager 2, Festlager 3, Einspannung 4 – jedes Lager überträgt zusätzlich ein Moment.", "Loslager 1 (Moment), Festlager 2 (Kraft und Moment), Einspannung 3 (drei Kräfte).", "Loslager 0, Festlager 1, Einspannung 2 – nur die Einspannung überträgt Kräfte in zwei Richtungen."], "musterantwort": "Für jede gesperrte Bewegungsmöglichkeit tritt eine Lagerreaktion auf: Für jede gesperrte Translation eine Kraft, für jede gesperrte Rotation ein Moment. Das Loslager sperrt nur die Verschiebung normal zur Auflagerfläche (1 Kraft), das Festlager beide Verschiebungen (2 Kräfte), die feste Einspannung zusätzlich die Verdrehung (2 Kräfte + 1 Moment). Ein ebener Körper braucht für statisch bestimmte Lagerung insgesamt 3 geeignete Lagerreaktionen.", "erklaerung": "Gesperrte Translation → Kraft, gesperrte Rotation → Moment.", "seiten": "MEC1 Ausarbeitung, 1.3 Gelenke (Lager)"},
  {"thema": "festigkeit", "quelle": "MEC1-Prüfungsfragen 2014", "frage": "Wo liegt bei reiner (gerader) Biegung ohne Normalkraft die neutrale Faser, und warum?", "richtig": "Im Flächenschwerpunkt, weil N = −(E/R)·∫y dA = 0 ein verschwindendes statisches Moment verlangt.", "falsch": ["Immer in halber Querschnittshöhe, weil Zug- und Druckzone bei Biegung stets gleich hoch sein müssen.", "In der Randfaser mit der größeren Breite, weil dort die Spannung am kleinsten ist.", "Im Flächenschwerpunkt, weil dort das Flächenträgheitsmoment J = ∫y² dA verschwindet."], "musterantwort": "Mit dem linearen Dehnungsverlauf εx = −y/R und σ = E·εx muss die Normalkraft verschwinden: N = ∫σ dA = −(E/R)∫y dA = −(E/R)·y_S·A = 0. Das ist nur erfüllt, wenn y_S = 0, d. h. die x-Achse (neutrale Faser) durch den Flächenschwerpunkt geht. Bei unsymmetrischen Profilen liegt sie daher nicht in halber Höhe.", "erklaerung": "Neutrale Faser = Schwerpunktachse; bei T- oder ungleichen I-Profilen nicht in der Mitte.", "seiten": "Prüfungsfragen 2014, Festigkeitslehre – Reine Biegung"},
  {"thema": "festigkeit", "quelle": "MEC1-Prüfungsfragen 2014", "frage": "Welche Form hat das lineare Materialgesetz für isotrope Werkstoffe bei zusätzlicher Temperaturänderung ΔT (Richtung x)?", "richtig": "εx = (1/E)·[σxx − ν(σyy + σzz)] + α·ΔT; Schubverzerrungen bleiben γ = τ/G.", "falsch": ["εx = (1/E)·[σxx + ν·(σyy + σzz)] + α·ΔT; zusätzlich gilt für die Schiebungen γ = τ/G + α·ΔT.", "εx = (1/E)·[σxx − ν·(σyy + σzz)] − α·ΔT; die Wärmedehnung verkürzt immer.", "εx = E·[σxx − ν·(σyy + σzz)] + α·ΔT; Schubverzerrungen γ = G·τ."], "musterantwort": "Aus dem Zugversuch folgt σ = E·ε und die Querdehnung εq = −ν·ε; Überlagerung für alle drei Richtungen ergibt εx = (1/E)[σxx − ν(σyy + σzz)], analog εy, εz, sowie γ = τ/G mit G = E/(2(1+ν)). Eine gleichmäßige Erwärmung eines freien Körpers erzeugt in allen Richtungen dieselbe Dehnung α·ΔT, aber keine Scherung und keine Spannung – sie wird zu den Normaldehnungen addiert.", "erklaerung": "Wärmedehnung ist reine Normaldehnung – keine Schubverzerrung, frei ausgedehnt keine Spannung.", "seiten": "Prüfungsfragen 2014, Festigkeitslehre – Spannung und Dehnung"},
  {"thema": "statik", "quelle": "MEC1-Prüfung 23.01.2017", "frage": "Aufgabe 1 (Fachwerk): Ebenes Fachwerk aus 6 Feldern (a = 1 m) mit Ober- und Untergurt, 7 Pfosten und 6 Diagonalen, gelagert auf einem Festlager und einem Loslager. Ist das Fachwerk statisch bestimmt?", "richtig": "Ja: k = 14 Knoten, s = 25 Stäbe, r = 3 Lagerreaktionen → 2·14 = 28 = 25 + 3.", "falsch": ["Nein, einfach statisch überbestimmt: k = 14, s = 26, r = 3 → 2k = 28 < 29.", "Nein, unterbestimmt: k = 14, s = 25, r = 2 → 28 > 27.", "Ja: k = 12, s = 21, r = 3 → 2·12 = 24 = 21 + 3."], "musterantwort": "Knoten: 7 unten + 7 oben = 14. Stäbe: 6 Obergurt + 6 Untergurt + 7 Pfosten + 6 Diagonalen = 25. Lagerreaktionen: Festlager 2 + Loslager 1 = 3. Mit 2k = 28 = s + r = 28 ist die Abzählbedingung erfüllt; da das Fachwerk aus Dreiecken aufgebaut ist, ist es statisch bestimmt.", "erklaerung": "Pfosten zählen: bei n Feldern gibt es n+1 Pfosten.", "seiten": "Prüfung 23.01.2017, Aufgabe 1.1"},
  {"thema": "statik", "quelle": "MEC1-Prüfung 23.01.2017", "frage": "Aufgabe 1 (Fachwerk, Spannweite 6a, a = 1 m): Lasten 30 kN horizontal am linken oberen Knoten (Höhe a), 30 kN vertikal bei x = a und 50 kN vertikal bei x = 3a (Untergurt). Festlager A links, Loslager B rechts. Wie groß sind die Auflagerkräfte?", "richtig": "A_H = 30 kN (nach links), A_V = 45 kN, B_V = 35 kN.", "falsch": ["A_H = 30 kN (nach links), A_V = 50 kN, B_V = 30 kN (Momente ohne Horizontalkraft).", "A_H = 0 kN, A_V = 45 kN, B_V = 35 kN.", "A_H = 30 kN (nach links), A_V = 40 kN, B_V = 40 kN."], "musterantwort": "ΣH = 0: A_H + 30 = 0 → A_H = −30 kN (also 30 kN nach links). ΣM_A = 0: B_V·6a − 30·a − 50·3a − 30·a = 0 (die Horizontalkraft hat den Hebelarm a) → B_V = (30 + 150 + 30)/6 = 35 kN. ΣV = 0: A_V = 30 + 50 − 35 = 45 kN.", "erklaerung": "Horizontalkraft in Höhe a erzeugt ebenfalls ein Moment um A – nicht vergessen.", "seiten": "Prüfung 23.01.2017, Aufgabe 1.2 (Lösung Bsp. 1, S. 1)"},
  {"thema": "statik", "quelle": "MEC1-Prüfung 23.01.2017", "frage": "Aufgabe 1 (Fachwerk): Am rechten oberen Eckknoten treffen nur der Obergurtstab 4 und der Endpfosten 3 zusammen, der Knoten ist unbelastet. Wie groß sind S3 und S4?", "richtig": "S3 = S4 = 0 (Nullstäbe).", "falsch": ["S3 = 35 kN Druck, S4 = 0.", "S3 = 0, S4 = 35 kN Zug.", "S3 = S4 = 24,7 kN Druck."], "musterantwort": "Am unbelasteten Knoten mit zwei nicht kollinearen Stäben liefert ΣH = 0 direkt S4 = 0 und ΣV = 0 direkt S3 = 0. Beide Stäbe sind Nullstäbe; die Lagerkraft B wird über die Diagonale 2 und den Untergurt 1 abgetragen.", "erklaerung": "Unbelasteter Knoten mit zwei nicht fluchtenden Stäben → beide Nullstäbe.", "seiten": "Prüfung 23.01.2017, Aufgabe 1.3 (Lösung Bsp. 1, S. 1)"},
  {"thema": "statik", "quelle": "MEC1-Prüfung 23.01.2017", "frage": "Aufgabe 1 (Fachwerk): Am rechten Lagerknoten (B_V = 35 kN) greifen der Untergurtstab 1 (horizontal), die 45°-Diagonale 2 und der Nullstab 3 an. Wie groß sind S1 und S2?", "richtig": "S2 = −35·√2 ≈ −49,5 kN (Druck), S1 = +35 kN (Zug).", "falsch": ["S2 = +49,5 kN (Zug), S1 = −35 kN (Druck), da die Lagerkraft am Stab zieht.", "S2 = −35 kN (Druck), S1 = +35 kN (Zug).", "S2 = −24,7 kN (Druck), S1 = +17,5 kN (Zug)."], "musterantwort": "ΣV = 0: B_V + S2·sin45° = 0 → S2 = −35/(1/√2) = −49,5 kN (Druckstab). ΣH = 0: −S1 − S2·cos45° = 0 → S1 = −(−49,5)·(1/√2) = +35 kN (Zug).", "erklaerung": "Stabkräfte als Zug ansetzen – das Vorzeichen zeigt dann Zug (+) oder Druck (−).", "seiten": "Prüfung 23.01.2017, Aufgabe 1.3 (Lösung Bsp. 1, S. 1)"},
  {"thema": "statik", "quelle": "MEC1-Prüfung 23.01.2017", "frage": "Aufgabe 1 (Fachwerk): Der Pfosten 7 steht über dem Untergurtknoten bei x = 3a, an dem die 50-kN-Last angreift und sonst nur die beiden Untergurtstäbe 5 und 6 anschließen. Holz: σ_zul = 1 kN/cm², Breite 5 cm. Welche Stabkraft hat Stab 7 und welche Höhe h ist nötig?", "richtig": "S7 = 50 kN (Zug); A = 50 cm² → h = 10 cm (Breite 5 cm).", "falsch": ["S7 = 25 kN (Zug); A = 25 cm² → h = 5 cm.", "S7 = 50 kN (Druck); A = 50 cm² → h = 2,5 cm.", "S7 = 70,7 kN (Zug), da 50 kN·√2; A = 70,7 cm² → h ≈ 14,1 cm."], "musterantwort": "Am Untergurtknoten bei x = 3a liegen die Stäbe 5 und 6 horizontal; ΣV = 0 ergibt daher S7 − 50 kN = 0 → S7 = 50 kN Zug. Erforderliche Fläche A = S7/σ_zul = 50 kN / (1 kN/cm²) = 50 cm². Mit b = 5 cm: h = 50/5 = 10 cm. (Untergurt dort: S5 = S6 = 105 kN Zug.)", "erklaerung": "Vertikale Last am Knoten mit nur horizontalen Nachbarstäben geht vollständig in den Pfosten.", "seiten": "Prüfung 23.01.2017, Aufgabe 1.3/1.4 (Lösung Bsp. 1, S. 2)"},
  {"thema": "statik", "quelle": "MEC1-Prüfung 23.01.2017", "frage": "Aufgabe 2 (Biegeträger, 8 m, Festlager A links, Loslager B rechts): Bei x = 4 m sitzt ein 1 m hoher Kragarm mit einer horizontalen Kraft 2 kN an der Spitze; auf x = 4…8 m wirkt q = 1 kN/m. Wie groß sind die Auflagerkräfte?", "richtig": "A_H = 2 kN (nach links), A_V = 0,75 kN, B_V = 3,25 kN.", "falsch": ["A_H = 2 kN (nach links), A_V = 1,0 kN, B_V = 3,0 kN.", "A_H = 0 kN, da der Kragarm die Horizontalkraft aufnimmt; A_V = 0,75 kN, B_V = 3,25 kN.", "A_H = 2 kN (nach links), A_V = 1,25 kN, B_V = 2,75 kN."], "musterantwort": "ΣH = 0: A_H = −2 kN (2 kN nach links). ΣM_A = 0: B_V·8 − (1·4)·6 − 2·1 = 0 (Streckenlast-Resultierende 4 kN bei x = 6 m, Horizontalkraft mit Hebelarm 1 m) → B_V = 26/8 = 3,25 kN. ΣV = 0: A_V = 4 − 3,25 = 0,75 kN.", "erklaerung": "Die Horizontalkraft am Kragarm wirkt über ihren Hebelarm 1 m auch auf das Momentengleichgewicht.", "seiten": "Prüfung 23.01.2017, Aufgabe 2.1 (Lösung Bsp. 2)"},
  {"thema": "statik", "quelle": "MEC1-Prüfung 23.01.2017", "frage": "Aufgabe 2 (Biegeträger, A_V = 0,75 kN, B_V = 3,25 kN, q = 1 kN/m auf 4…8 m, Versatzmoment 2 kNm bei x = 4 m): Wo tritt das maximale Biegemoment auf und wie groß ist es?", "richtig": "Bei x = 4,75 m: M_max = 3,25²/2 ≈ 5,28 kNm.", "falsch": ["Bei x = 4 m: M_max = 3,0 kNm (Wert links vom Kragarm).", "Bei x = 6 m (Mitte der Streckenlast): M_max = 4,5 kNm.", "Bei x = 4 m, rechts vom Kragarm: M_max = 5,0 kNm (Wert nach dem Momentensprung)."], "musterantwort": "Links von x = 4 m: M = 0,75·x, also 3 kNm bei x = 4 m; dort springt M durch das Versatzmoment 2 kN·1 m auf 5 kNm. Rechts davon (ξ = Abstand von B): M = 3,25·ξ − ξ²/2; Q = 0 bei ξ = 3,25 m, d. h. x = 4,75 m. M_max = 3,25²/2 = 5,28 kNm.", "erklaerung": "Einzelmoment → Sprung im M-Verlauf; Maximum trotzdem bei Q = 0 suchen.", "seiten": "Prüfung 23.01.2017, Aufgabe 2.3 (Lösung Bsp. 2, S. 2)"},
  {"thema": "festigkeit", "quelle": "MEC1-Prüfung 23.01.2017", "frage": "Aufgabe 2: Unsymmetrisches I-Profil (Höhe 100 mm, Obergurt 100×10, Steg 4×80, Untergurt 80×10 mm), M_max = 5,28 kNm. Wo liegt der Schwerpunkt und wie groß ist die maximale Biegespannung?", "richtig": "y_S ≈ 54,2 mm von unten, J ≈ 3,79·10⁶ mm⁴, σ_max ≈ 75,5 N/mm² unten.", "falsch": ["y_S = 50 mm (halbe Profilhöhe), J ≈ 3,79·10⁶ mm⁴, σ_max ≈ 69,6 N/mm² an beiden Rändern.", "y_S ≈ 54,2 mm von unten, J ≈ 3,79·10⁶ mm⁴, σ_max ≈ 63,7 N/mm² (Oberkante).", "y_S ≈ 45,8 mm von unten, J ≈ 2,94·10⁶ mm⁴, σ_max ≈ 82,2 N/mm²."], "musterantwort": "A = 1000 + 320 + 800 = 2120 mm²; y_S = (1000·95 + 320·50 + 800·5)/2120 = 54,25 mm von unten. J = Σ(b·h³/12 + A·d²) = 3,79·10⁶ mm⁴. Größter Randabstand e_u = 54,25 mm (oben 45,75 mm), also σ_max = M·e_u/J = 5,28·10⁶·54,25/3,79·10⁶ ≈ 75,5 N/mm²; an dieser Stelle ist N = 0.", "erklaerung": "Maximale Spannung an der Randfaser mit dem größten Abstand zur Schwerpunktachse.", "seiten": "Prüfung 23.01.2017, Aufgabe 2.4 (Lösung Bsp. 2, S. 2)"},
  {"thema": "reibung", "quelle": "MEC1-Prüfung 16.02.2017", "frage": "Aufgabe 1 (Stabwerk mit Reibung): Zwei gelenkig verbundene Stäbe (Länge a, Masse m bzw. Länge 2a, Masse 2m) stehen rechtwinklig auf dem Boden (p = a/√5, q = 4a/√5, h = 2a/√5). Wie groß sind die Aufstandskräfte?", "richtig": "Links (kurzer Stab): N_A = 1,7·mg; rechts (langer Stab): N_B = 1,3·mg.", "falsch": ["Links: N_A = 1,0·mg; rechts: N_B = 2,0·mg (jeder Fuß trägt genau sein eigenes Stabgewicht).", "Links: N_A = 1,3·mg; rechts: N_B = 1,7·mg.", "Links: N_A = 1,5·mg; rechts: N_B = 1,5·mg (symmetrisch aufgeteilt)."], "musterantwort": "Gesamtsystem, Momente um den linken Fußpunkt: N_B·√5a = mg·p/2 + 2mg·(p + q/2) = mg·a/(2√5) + 6mg·a/√5 → N_B = 6,5mg/5 = 1,3 mg. ΣV: N_A = 3mg − 1,3mg = 1,7 mg. Der kurze Stab steht steiler und näher am Gelenk, daher trägt sein Fuß mehr als sein Eigengewicht.", "erklaerung": "Aufstandskräfte nicht nach Stabgewicht verteilen – Momentengleichgewicht am Gesamtsystem.", "seiten": "Prüfung 16.02.2017, Aufgabe 1.2 (Lösung Bsp. 1, S. 2)"},
  {"thema": "reibung", "quelle": "MEC1-Prüfung 16.02.2017", "frage": "Aufgabe 1 (Stabwerk, N_A = 1,7 mg, N_B = 1,3 mg): Wie groß sind die Reibungskräfte und wie groß muss der Haftreibungskoeffizient μ mindestens sein?", "richtig": "H_A = H_B = 0,6·mg; μ_min = 0,6/1,3 ≈ 0,46 (maßgebend ist der lange Stab).", "falsch": ["H_A = H_B = 0,6·mg; μ_min = 0,6/1,7 ≈ 0,35 (maßgebend ist der steilere, kurze Stab).", "H_A = H_B = 0,5·mg; μ_min = 0,5/1,3 ≈ 0,38.", "H_A = H_B = 0,6·mg; μ_min = 0,6/3,0 = 0,20 (Gesamtgewicht)."], "musterantwort": "Momentengleichgewicht des kurzen Stabes um das Gelenk: N_A·p − H_A·h − mg·p/2 = 0 → H_A = p(N_A − mg/2)/h = (1/2)(1,7 − 0,5)mg = 0,6 mg. Aus ΣH = 0 folgt H_B = 0,6 mg (entgegengesetzt). Haftbedingung H ≤ μ·N an beiden Füßen: μ ≥ 0,6/1,7 = 0,35 und μ ≥ 0,6/1,3 = 0,46 → μ_min ≈ 0,46 (= 6/13).", "erklaerung": "Bei gleicher Reibkraft rutscht zuerst der Fuß mit der kleineren Normalkraft.", "seiten": "Prüfung 16.02.2017, Aufgabe 1.2/1.3 (Lösung Bsp. 1, S. 2)"},
  {"thema": "statik", "quelle": "MEC1-Prüfung 16.02.2017", "frage": "Aufgabe 2 (Biegeträger mit Kragarm): Festlager A bei x = 0, Loslager B bei x = 4 m, Kragarm bis 6 m; q = 3 kN/m auf 0…4 m und 2 kN/m auf 4…6 m. Wie groß sind die Auflagerkräfte?", "richtig": "A_V = 5 kN, B_V = 11 kN (A_H = 0) aus ΣM_A = 0 und ΣV = 0.", "falsch": ["A_V = 6 kN, B_V = 10 kN (A_H = 0).", "A_V = 8 kN, B_V = 8 kN (A_H = 0).", "A_V = 7 kN, B_V = 9 kN (A_H = 0, Kragarmlast zur Hälfte auf A)."], "musterantwort": "Resultierende: 3·4 = 12 kN bei x = 2 m, 2·2 = 4 kN bei x = 5 m. ΣM_A = 0: B_V·4 − 12·2 − 4·5 = 0 → B_V = 44/4 = 11 kN. ΣV = 0: A_V = 16 − 11 = 5 kN. Keine Horizontallasten → A_H = 0.", "erklaerung": "Kragarmlast vergrößert B und entlastet A.", "seiten": "Prüfung 16.02.2017, Aufgabe 2.1 (Lösung Bsp. 2)"},
  {"thema": "statik", "quelle": "MEC1-Prüfung 16.02.2017", "frage": "Aufgabe 2 (Biegeträger, A_V = 5 kN, B_V = 11 kN): Wo tritt das betragsmäßig größte Biegemoment auf und wie groß ist es?", "richtig": "Bei x = 5/3 m ≈ 1,67 m: M_max = 25/6 ≈ 4,17 kNm.", "falsch": ["Über dem Lager B: |M| = 4,0 kNm, weil das Stützmoment immer maßgebend ist.", "In Feldmitte x = 2 m: M_max = 4,0 kNm.", "Bei x = 5/3 m: M_max = 8,33 kNm."], "musterantwort": "Feld 0…4 m: Q(x) = 5 − 3x = 0 bei x = 5/3 m; M = 5·(5/3) − 1,5·(5/3)² = 25/6 ≈ 4,17 kNm. Über B (Kragarm): M_B = −2·2²/2 = −4 kNm. Betragsmäßig maßgebend ist also das Feldmoment 4,17 kNm.", "erklaerung": "Feld- und Stützmoment immer beide vergleichen – hier knapp das Feldmoment.", "seiten": "Prüfung 16.02.2017, Aufgabe 2.5 (Lösung Bsp. 2, S. 2)"},
  {"thema": "festigkeit", "quelle": "MEC1-Prüfung 16.02.2017", "frage": "Aufgabe 2: T-ähnliches Profil (Höhe 100 mm, Obergurt 100×10, Steg 10×80, Untergurt 40×10 mm; y_S ≈ 62,3 mm von unten, J ≈ 2,94·10⁶ mm⁴). Wie groß ist die maximale Spannung und ist sie Zug oder Druck?", "richtig": "σ_max ≈ 88,2 N/mm², Zug, Unterkante bei x ≈ 1,67 m.", "falsch": ["σ_max ≈ 88,2 N/mm² Druck an der Unterkante bei x ≈ 1,67 m.", "σ_max ≈ 53,4 N/mm², Druck, an der Oberkante bei x ≈ 1,67 m (größerer Gurt oben).", "σ_max ≈ 84,7 N/mm² Zug an der Unterkante über dem Lager B."], "musterantwort": "A = 1000 + 800 + 400 = 2200 mm², y_S = (1000·95 + 800·50 + 400·5)/2200 = 62,27 mm; J ≈ 2,94·10⁶ mm⁴. Das positive Feldmoment 4,17 kNm erzeugt unten Zug: σ = 4,17·10⁶·62,27/2,94·10⁶ ≈ 88,2 N/mm². Über B (M = −4 kNm) ergibt sich unten nur 84,7 N/mm² Druck, oben 51,3 N/mm² Zug.", "erklaerung": "Positives Moment: Zug unten; großer Randabstand unten bei schmalem Untergurt.", "seiten": "Prüfung 16.02.2017, Aufgabe 2.6"},
  {"thema": "festigkeit", "quelle": "FEL4-Klausur 2019-11-04", "frage": "Was versteht man unter „Zyklischem Kriechen“ (Ratcheting)?", "richtig": "Keine stabile Hysterese: Die Schleife wandert mit jedem Zyklus zu größeren Dehnungen aus.", "falsch": ["Die Dehnung nimmt unter konstanter Last bei hoher Temperatur zeitabhängig zu, ohne zyklische Belastung.", "Nach anfänglichen plastischen Lastzyklen stellt sich ein dauerhaft rein elastisches Verhalten ein.", "Bei konstanter Spannungsamplitude nimmt die Dehnungsamplitude von Zyklus zu Zyklus ab."], "musterantwort": "Beim zyklischen Kriechen (Ratcheting) stabilisiert sich die Hystereseschleife nicht, sondern wandert sukzessive zu höheren Dehnungen aus; die Gesamtdehnung wächst in jedem Lastzyklus. Das führt meist schon nach wenigen Lastwechseln zum Versagen (vgl. Abreißen eines Drahtes durch Hin- und Herbiegen).", "erklaerung": "Ratcheting = Dehnung „ratscht“ pro Zyklus weiter – Gegenteil von Einspielen.", "seiten": "FEL4-Klausur 04.11.2019, Theoriefrage 1; Fragenkatalog FEL, Frage 3"},
  {"thema": "festigkeit", "quelle": "FEL4-Klausur 2019-11-04", "frage": "Zeigen Sie, dass der Spannungstensor symmetrisch sein muss – welche Begründung ist richtig?", "richtig": "Momentengleichgewicht am Volumenelement um die y-Achse liefert τzx = τxz.", "falsch": ["Kräftegleichgewicht in x-Richtung am Volumenelement liefert direkt τzx = τxz.", "Weil Normalspannungen σii = σjj symmetrisch sind, gilt dies automatisch auch für die Schubspannungen.", "Der Tensor ist per Definition symmetrisch, weil der erste und zweite Index vertauschbar gewählt werden."], "musterantwort": "Ein Volumenelement dx·dy·dz muss auch im Momentengleichgewicht sein. Um die y-Achse durch den Würfelmittelpunkt wirken nur τzx (auf den z-Flächen, Hebelarm dz/2) und τxz (auf den x-Flächen, Hebelarm dx/2): 2·(τzx·dx·dy)·dz/2 − 2·(τxz·dy·dz)·dx/2 = 0 → τzx = τxz (zugeordnete Schubspannungen). Analog für die anderen Achsen, also σij = σji.", "erklaerung": "Symmetrie aus dem Momenten-, nicht aus dem Kräftegleichgewicht.", "seiten": "FEL4-Klausur 04.11.2019, Theoriefrage 2; Prüfungsfragen 2014, Spannungstensor"},
  {"thema": "festigkeit", "quelle": "FEL4-Klausur 2019-11-04", "frage": "Was versteht man unter den „Mischungsregeln“ bei faserverstärkten Kunststoffen (FVK)?", "richtig": "Faser und Matrix als Federn: längs zur Faser parallel geschaltet, quer dazu in Serie.", "falsch": ["Faser und Matrix als Federn: in Faserlängsrichtung in Serie geschaltet, quer zur Faser parallel geschaltet.", "Die Steifigkeit des Verbunds ist in allen Richtungen der Mittelwert aus Faser- und Matrixmodul.", "Weiche Fasern werden in eine harte Matrix eingebettet, deren Festigkeit die Fasern übernehmen."], "musterantwort": "Die Mischungsregeln ersetzen den Verbund durch zwei vereinfachte Modelle: Längs (gleiche Dehnung) Parallelschaltung von Faser- und Matrix-„Feder“: E∥ = φ·E_F + (1−φ)·E_M. Quer (gleiche Spannung) Serienschaltung: 1/E⊥ = φ/E_F + (1−φ)/E_M. Dabei ist φ der Faservolumenanteil; der Verbund ist längs deutlich steifer als quer.", "erklaerung": "Längs: gleiche Dehnung (parallel); quer: gleiche Spannung (seriell).", "seiten": "FEL4-Klausur 04.11.2019 und 09.07.2019, Theoriefrage 3; Fragenkatalog FEL, Frage 52"},
  {"thema": "festigkeit", "quelle": "FEL4-Klausur 2019-11-04", "frage": "Welche Größen des Spannungstensors sind invariant gegenüber einer Koordinatentransformation?", "richtig": "Die Invarianten I₁ (Spur), I₂ und I₃ (Determinante) sowie die Hauptspannungen.", "falsch": ["Die drei Normalspannungen σxx, σyy und σzz einzeln, da sie auf der Hauptdiagonale stehen.", "Die drei Schubspannungen τxy, τyz und τzx einzeln.", "Nur die größte Schubspannung, alle anderen Kennwerte ändern sich."], "musterantwort": "Bei Drehung des Koordinatensystems ändern sich die einzelnen Komponenten des Tensors im Allgemeinen. Unverändert bleiben die Koeffizienten des charakteristischen Polynoms: I₁ = Spur = σxx+σyy+σzz, I₂ = Summe der Hauptminoren 2. Ordnung, I₃ = det[σij] – und damit auch die Hauptspannungen σ₁, σ₂, σ₃.", "erklaerung": "Die Summe σxx+σyy+σzz ist invariant – die einzelnen Diagonalelemente nicht.", "seiten": "FEL4-Klausur 04.11.2019, Theoriefrage 4; Fragenkatalog FEL, Frage 6/17"},
  {"thema": "festigkeit", "quelle": "FEL4-Klausur 2019-07-09", "frage": "Was versteht man unter „Einspielen“ (Shake-down)?", "richtig": "Nach anfänglichem Plastizieren unter wiederholter Last verhält sich der Bauteil nur noch elastisch.", "falsch": ["Die Hystereseschleife wandert mit jedem Lastzyklus zu höheren Dehnungen aus.", "Unter wiederholter Belastung plastiziert der Bauteil in jedem Zyklus stärker und versagt.", "Der Bauteil wird vor der Inbetriebnahme einmal bis zur Traglast belastet und anschließend wieder vollständig entlastet."], "musterantwort": "Einspielen bezeichnet das Verhalten eines Bauteils unter wiederholter Belastung, bei dem nach anfänglichen plastischen Verformungen (Aufbau von Eigenspannungen) nur noch elastische Verformungen auftreten. Es stellt sich ein stabiler Zustand ohne weitere plastische Dehnungsakkumulation ein.", "erklaerung": "Einspielen = stabil elastisch nach Anfangsplastizierung; Ratcheting = Gegenteil.", "seiten": "FEL4-Klausur 09.07.2019, Theoriefrage 1; Fragenkatalog FEL, Frage 50"},
  {"thema": "festigkeit", "quelle": "FEL4-Klausur 2019-07-09", "frage": "Was sind Hauptnormalspannungen und wie berechnet man sie aus dem Spannungstensor?", "richtig": "Normalspannungen in schubspannungsfreien Schnitten; aus det([σij] − σ·1) = 0.", "falsch": ["Die Diagonalelemente σxx, σyy, σzz des Tensors, und zwar in einem beliebigen Koordinatensystem.", "Normalspannungen in Schnittebenen mit maximaler Schubspannung; aus der Spur des Tensors.", "Die Mittelwerte der Normalspannungen; σ_H = (σxx+σyy+σzz)/3."], "musterantwort": "Gesucht sind Schnittebenen, deren Spannungsvektor parallel zur Normalen n ist (keine Schubspannung): [σij]·n = σ·n. Das führt auf das Eigenwertproblem ([σij] − σ·1)·n = 0; nichttriviale Lösungen existieren für det([σij] − σ·1) = 0. Die drei Lösungen σ₁, σ₂, σ₃ sind die Hauptnormalspannungen, die Eigenvektoren die Hauptrichtungen.", "erklaerung": "Hauptspannungen = Eigenwerte, Hauptrichtungen = Eigenvektoren; dort ist τ = 0.", "seiten": "FEL4-Klausur 09.07.2019, Theoriefrage 2; Fragenkatalog FEL, Frage 8"},
  {"thema": "festigkeit", "quelle": "FEL4-Klausur 2019-07-09", "frage": "Wie hängt bei linear elastischem Material die volumetrische Dehnung ε_vol mit dem hydrostatischen Spannungsanteil σ_m zusammen?", "richtig": "σ_m = K·ε_vol mit ε_vol = εx+εy+εz und K = E/(3(1−2ν)) (σ_m = mittlere Normalspannung).", "falsch": ["σ_m = E·ε_vol mit ε_vol = εx·εy·εz und σ_m = σx+σy+σz (ohne Division durch 3).", "σ_m = G·ε_vol mit G = E/(2(1+ν)) als Kompressionsmodul.", "σ_m = K·ε_vol mit K = E/(3(1+2ν)), sodass K für ν = 0,5 endlich bleibt."], "musterantwort": "Die volumetrische Dehnung ist die relative Volumenänderung ΔV/V ≈ εx+εy+εz. Summiert man das Hooke’sche Gesetz über alle drei Richtungen, folgt ε_vol = (1−2ν)/E·(σx+σy+σz) = 3(1−2ν)/E·σ_m, also σ_m = K·ε_vol mit dem Kompressionsmodul K = E/(3(1−2ν)). Für ν → 0,5 wird K → ∞ (inkompressibel).", "erklaerung": "Kompressionsmodul K = E/(3(1−2ν)) – bei ν = 0,5 inkompressibel.", "seiten": "FEL4-Klausur 09.07.2019, Theoriefrage 4; Fragenkatalog FEL, Frage 20"},
  {"thema": "festigkeit", "quelle": "FEL4-Klausur 2019-07-09", "frage": "Was besagt der Satz von Castigliano?", "richtig": "Die Ableitung der Verzerrungsenergie nach einer Kraft ergibt die Verschiebung ihres Angriffspunkts in Kraftrichtung.", "falsch": ["Die partielle Ableitung der Verzerrungsenergie nach einer Verschiebung ergibt die Verzerrungsenergie selbst: U = ∂U/∂δ.", "Die zweite Ableitung der Verzerrungsenergie nach der Kraft ergibt die Durchbiegung: w = ∂²U/∂F².", "Die Verzerrungsenergie eines elastischen Körpers ist immer genau gleich der halben potentiellen Energie aller äußeren Lasten."], "musterantwort": "Für einen linear elastischen Körper gilt: Die partielle Ableitung der gespeicherten Verzerrungsenergie U nach einer äußeren Last Fᵢ liefert die Verschiebung δᵢ des Kraftangriffspunkts in Richtung dieser Kraft (Arbeitsweg). Beispiel Biegebalken: U = ∫M²/(2EI) dx, w_F = ∂U/∂F. Für Lagerkräfte mit Verschiebung null folgt ∂U/∂X = 0 (Satz von Menabrea) – so berechnet man statisch unbestimmte Systeme.", "erklaerung": "Castigliano: ∂U/∂F = δ; Menabrea: ∂U/∂X = 0 bei unverschieblichem Lager.", "seiten": "FEL4-Klausur 09.07.2019, Theoriefrage 5; Fragenkatalog FEL, Frage 44"},
  {"thema": "festigkeit", "quelle": "FEL4-Klausur 2019-07-09", "frage": "Beispiel 1: Kragbalken (Länge L = 1000 mm, Quadrat s = 10 mm, E = 7·10⁴ MPa) mit Endlast F und axialer Druckkraft P. Mit dem eingliedrigen Ritz-Ansatz w = a·x²: Bei welcher Axiallast P* wird die Näherung w(L) unendlich?", "richtig": "P* = 3·E·J/L² ≈ 175 N (mit J = s⁴/12 ≈ 833 mm⁴).", "falsch": ["P* = π²·E·J/(4L²) ≈ 144 N – das ist bereits das Ergebnis des Ritz-Ansatzes.", "P* = 2·E·J/L² ≈ 117 N (mit J = s⁴/12 ≈ 833 mm⁴).", "P* = 3·E·J/L² ≈ 700 N (mit J = s⁴/3 ≈ 3333 mm⁴)."], "musterantwort": "Π = (EJ/2)∫w″²dx − (P/2)∫w′²dx − F·w(L) = 2EJa²L − (2/3)Pa²L³ − FaL². ∂Π/∂a = 0 → a = F·L/(4EJ − (4/3)PL²). Der Nenner wird null für P* = 3EJ/L² = 3·7·10⁴·833,3/10⁶ ≈ 175 N. Die exakte Euler-Last des Kragstabs ist π²EJ/(4L²) ≈ 144 N – Ritz liefert eine obere Schranke.", "erklaerung": "Ritz überschätzt Knicklasten (zu steifer Ansatz) – 175 N > 144 N.", "seiten": "FEL4-Klausur 09.07.2019, Beispiel 1c"},
  {"thema": "festigkeit", "quelle": "FEL4-Klausur 2019-11-04", "frage": "Beispiel 2: Zylindrischer Behälter, R_m = 500 mm, t = 10 mm, Dampf-Innendruck p = 10 bar. Welche Spannungen liefern die Kesselformeln (nur Innendruckanteil)?", "richtig": "Umfangsspannung σ_φ = p·R/t = 50 MPa, Längsspannung σ_x = p·R/(2t) = 25 MPa (10 bar = 1 MPa).", "falsch": ["Umfangsspannung σ_φ = p·R/(2t) = 25 MPa, Längsspannung σ_x = p·R/t = 50 MPa.", "Umfangsspannung σ_φ = p·R/t = 500 MPa, Längsspannung σ_x = 250 MPa.", "Umfangsspannung σ_φ = p·R/t = 50 MPa, Längsspannung σ_x = 50 MPa (gleich groß in beiden Richtungen)."], "musterantwort": "10 bar = 1 MPa. Umfangsrichtung (Kesselformel): σ_φ = p·R_m/t = 1·500/10 = 50 MPa. Längsrichtung (geschlossener Behälter): σ_x = p·R_m/(2t) = 25 MPa. Das Wassergewicht erzeugt zusätzlich eine Biegespannung in Längsrichtung, die an A und B mit unterschiedlichem Vorzeichen überlagert wird.", "erklaerung": "Umfangsspannung ist doppelt so groß wie die Längsspannung – Rohre platzen längs auf.", "seiten": "FEL4-Klausur 04.11.2019, Beispiel 2a"},
  {"thema": "festigkeit", "quelle": "FEL4-Klausur 2014-07-11", "frage": "Beispiel 1 (Thermisches Plastizieren): Beidseitig fest eingespannter Stahlstab, E = 2,0·10⁵ N/mm², α = 10·10⁻⁶ 1/K, R_p = 200 MPa. Bei welcher Temperaturerhöhung ΔT* tritt gerade noch kein Plastizieren auf?", "richtig": "ΔT* = R_p/(E·α) = 100 K.", "falsch": ["ΔT* = R_p/(E·α) = 10 K.", "ΔT* = R_p·α/E = 10⁻⁸ K.", "ΔT* = R_p/(E·α·(1−ν)) ≈ 143 K."], "musterantwort": "Die Gesamtdehnung ist durch die Einspannung null: 0 = σ/E + α·ΔT → σ = −E·α·ΔT (Druck). Plastizieren beginnt bei |σ| = R_p: ΔT* = R_p/(E·α) = 200/(2·10⁵·10⁻⁵) = 100 K. Der Durchmesser spielt keine Rolle, ν ebenfalls nicht (einachsiger Zustand).", "erklaerung": "Behinderte Wärmedehnung: σ = −E·α·ΔT, unabhängig von Länge und Querschnitt.", "seiten": "FEL4-Klausur 11.07.2014, Beispiel 1a"},
  {"thema": "festigkeit", "quelle": "FEL4-Klausur 2014-07-11", "frage": "Beispiel 1 (Fortsetzung): Bilineares Material mit Tangentenmodul E_T = 1,0·10⁴ N/mm² nach R_p. Welche Spannung herrscht im eingespannten Stab bei ΔT = 3·ΔT* = 300 K?", "richtig": "ε_mech = −α·ΔT = −0,003; σ = −[R_p + E_T·(0,003 − R_p/E)] = −220 N/mm² (Druck).", "falsch": ["σ = −E·α·ΔT = −600 N/mm² (Druck), da das Hooke’sche Gesetz weiter gilt.", "σ = −R_p = −200 N/mm² (Druck), da nach dem Fließen keine Spannungssteigerung möglich ist.", "σ = −E_T·α·ΔT = −30 N/mm² (Druck)."], "musterantwort": "Wegen der Einspannung ist ε_mech = −α·ΔT = −10⁻⁵·300 = −0,003. Elastisch bis |ε| = R_p/E = 0,001, danach Steigung E_T: |σ| = 200 + 10⁴·(0,003 − 0,001) = 220 N/mm². Der Stab steht also unter 220 N/mm² Druck; ε_pl = ε_mech − σ/E = −0,003 + 0,0011 = −0,0019.", "erklaerung": "Bilinear: über R_p hinaus nur noch mit E_T weiter – nicht mit E und nicht konstant R_p.", "seiten": "FEL4-Klausur 11.07.2014, Beispiel 1c"},
  {"thema": "festigkeit", "quelle": "FEL-Fragenkatalog", "frage": "Wie unterscheiden sich die Fließbedingungen nach Tresca und nach v. Mises im ebenen Spannungszustand?", "richtig": "Tresca: Sechseck, konservativer; v. Mises: um 45° geneigte Ellipse.", "falsch": ["Tresca: Ellipse, weniger konservativ; v. Mises: Sechseck, das innerhalb der Tresca-Fläche liegt.", "Beide ergeben einen Kreis, Tresca mit dem Radius R_p, v. Mises mit √3·R_p.", "Tresca hängt nur von der hydrostatischen Spannung ab, v. Mises nur von der größten Hauptspannung."], "musterantwort": "Tresca: Fließen bei τ_max = R_p/2; in der σ₁-σ₂-Ebene entsteht ein Sechseck, das innerhalb der v.-Mises-Fläche liegt (konservativer). v. Mises: Fließen, wenn die Gestaltänderungsenergiedichte bzw. J₂ einen kritischen Wert erreicht; σ₁² − σ₁σ₂ + σ₂² = R_p² ist eine Ellipse mit um 45° geneigten Achsen. v. Mises stimmt für duktile Metalle besser mit Versuchen überein; beide sind unabhängig vom hydrostatischen Anteil.", "erklaerung": "Sechseck (Tresca) liegt innen – also auf der sicheren Seite.", "seiten": "Fragenkatalog FEL, Fragen 32, 34, 36"}
];

